export const MAX_JSON_BYTES=32*1024*1024,MAX_IMAGE_BYTES=1024*1024,MAX_TOTAL_BYTES=24*1024*1024,MAX_RGBA_BYTES=64*1024*1024,MAX_DIMENSION=2048;
const TOP=['buildId','format','images'], IMAGE=['basename','data','height','mime','sha256','songId','width'];
const exact=(v,keys)=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).length===keys.length&&keys.every(k=>Object.hasOwn(v,k));
const fail=code=>{throw new TypeError('INVALID_JACKETS:'+code)};
function metadata(catalog){if(!Array.isArray(catalog?.songs)||catalog.songs.length!==(catalog.dlcSource?.packId===8?83:78))return false;return catalog.songs.every(s=>s.jacket&&s.jacket.mime==='image/png'&&/^[a-f0-9]{64}$/u.test(s.jacket.sha256)&&Number.isSafeInteger(s.jacket.width)&&s.jacket.width>0&&s.jacket.width<=MAX_DIMENSION&&Number.isSafeInteger(s.jacket.height)&&s.jacket.height>0&&s.jacket.height<=MAX_DIMENSION)}
function decode64(s){if(typeof s!=='string'||s.length%4!==0||s.length>Math.ceil(MAX_IMAGE_BYTES/3)*4||/[^A-Za-z0-9+/=]/u.test(s)||!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/u.test(s))fail('base64');const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';if(s.endsWith('==')&&(alphabet.indexOf(s.at(-3))&15)!==0)fail('base64');if(s.endsWith('=')&&!s.endsWith('==')&&(alphabet.indexOf(s.at(-2))&3)!==0)fail('base64');const b=atob(s);const a=Uint8Array.from(b,c=>c.charCodeAt(0));if(a.length>MAX_IMAGE_BYTES)fail('image-size');return a}
function ihdr(b){if(b.length<33||![137,80,78,71,13,10,26,10].every((x,i)=>b[i]===x)||new TextDecoder().decode(b.subarray(12,16))!=='IHDR')fail('png');const v=new DataView(b.buffer,b.byteOffset,b.byteLength);if(v.getUint32(8)!==13)fail('png');return {width:v.getUint32(16),height:v.getUint32(20)}}
export function jacketsEnabled(catalog){return metadata(catalog)}
export async function validateJackets(file,catalog,{digest=async b=>new Uint8Array(await crypto.subtle.digest('SHA-256',b)).reduce((s,x)=>s+x.toString(16).padStart(2,'0'),'')}={}){if(!metadata(catalog))fail('catalog-metadata');if(!file||file.size>MAX_JSON_BYTES)fail('json-size');const doc=JSON.parse(await file.text());if(!exact(doc,TOP)||doc.format!=='infalsus-jackets-v1'||doc.buildId!=='25594228'||!Array.isArray(doc.images)||doc.images.length!==catalog.songs.length)fail('shape');let total=0,rgba=0;const bytes=[],songs=[...catalog.songs].sort((a,b)=>a.songId-b.songId);for(let i=0;i<songs.length;i++){const x=doc.images[i],s=songs[i];if(!exact(x,IMAGE)||x.songId!==s.songId||x.basename!==s.basename||x.mime!=='image/png'||x.width!==s.jacket.width||x.height!==s.jacket.height||x.sha256!==s.jacket.sha256)fail('join');const b=decode64(x.data);total+=b.length;if(total>MAX_TOTAL_BYTES)fail('total-size');const d=ihdr(b);if(d.width!==x.width||d.height!==x.height||d.width>MAX_DIMENSION||d.height>MAX_DIMENSION)fail('dimensions');rgba+=d.width*d.height*4;if(rgba>MAX_RGBA_BYTES)fail('rgba-budget');if(await digest(b)!==x.sha256)fail('sha256');bytes.push(b)}return bytes}
export function createJacketController({catalog,onImages=()=>{},digest,decode=async b=>createImageBitmap(new Blob([b],{type:'image/png'})),createURL=b=>URL.createObjectURL(new Blob([b],{type:'image/png'})),revokeURL=u=>URL.revokeObjectURL(u)}={}){let generation=0,urls=[];const revoke=items=>{for(const u of items)revokeURL(u)};const clear=()=>{const old=urls;urls=[];revoke(old);onImages([])};const release=()=>{generation++;clear()};return {enabled:jacketsEnabled(catalog),async load(file){const token=++generation;clear();let bytes=[];try{bytes=await validateJackets(file,catalog,{digest});const songs=[...catalog.songs].sort((a,b)=>a.songId-b.songId);for(let i=0;i<bytes.length;i++){if(token!==generation)return false;const image=await decode(bytes[i]);try{const expected=songs[i].jacket;if(!image||!Number.isSafeInteger(image.width)||!Number.isSafeInteger(image.height)||image.width!==expected.width||image.height!==expected.height)fail('decoded-dimensions')}finally{try{image?.close?.()}catch{}}if(token!==generation)return false}if(token!==generation)return false;const created=[];try{for(const b of bytes)created.push(createURL(b));}catch(e){revoke(created);throw e}if(token!==generation){revoke(created);return false}urls=created;onImages(urls);return true}catch(e){if(token===generation)clear();throw e}finally{bytes=[]}},reset:release,unload:release,get urls(){return [...urls]}}}
